class Solution {
public:
    int constrainedSubsetSum(vector<int>& nums, int k) {
        int n = nums.size();
        deque<pair<int,int>> dq; // (index, dp value), strictly decreasing by value
        int ans = INT_MIN;
        for (int i = 0; i < n; i++) {
            while (!dq.empty() && dq.front().first < i - k) {
                dq.pop_front();
            }
            int best = dq.empty() ? 0 : dq.front().second;
            int cur = nums[i] + (best > 0 ? best : 0);
            while (!dq.empty() && dq.back().second <= cur) {
                dq.pop_back();
            }
            dq.push_back({i, cur});
            if (cur > ans) ans = cur;
        }
        return ans;
    }
};
